def exceptional_collision_masks(first, second, q):
    masks = set()
    for reps_by_value, swapped in ((first, False), (second, True)):
        for reps in reps_by_value.values():
            rep_masks = []
            for i, j, t in reps:
                if not swapped:
                    mask = (_sage_const_1  << i) | (_sage_const_1  << j) | (_sage_const_1  << (q + t))
                else:
                    mask = (_sage_const_1  << (q + i)) | (_sage_const_1  << (q + j)) | (_sage_const_1  << t)
                rep_masks.append(mask)
            for a, b in combinations(rep_masks, _sage_const_2 ):
                masks.add(a | b)
    return masks


def field_audit(q):
    F = GF(q, name='z')
